import { UPLOAD_ACTION } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case UPLOAD_ACTION.UPLOAD_POLICY_FILE:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
