import moment from 'moment'
import {
  Form,
  DatePicker,
  Select,
  Upload,
  Button,
  Radio,
  Icon,
  InputNumber,
  Checkbox,
  Row,
  Col,
  Input
} from 'antd'
import get from 'lodash/get'
import MultiUploadImgView from '../PasarApp/containers/Agent/components/MultiUploadImgView'
import MultiFileWithRadio from '../PasarApp/containers/Agent/components/MultiFileWithRadio'
import MultipleHybridFiles from '../PasarApp/containers/Agent/components/MultiHybridFiles'
import UploadImgPreviewContainer from '../PasarApp/containers/Agent/components/UploadImgPreview'

const getInitialValue = (type, defaultValue) => {
  let value =
    type === 'date' && defaultValue
      ? moment(defaultValue, 'YYYY-MM-DD')
      : defaultValue
  if (type === 'vehicle_manufacturing_year') {
    value = parseInt(defaultValue, 10)
  }
  return value
}

const renderFormItems = ({
  name,
  title,
  placeholder,
  type,
  required = true,
  disabled = false,
  isEnableType = false,
  defaultValue = '',
  subTitle,
  runtimeRequestParams = '',
  data = [],
  radioDataKey = '',
  min = 0,
  max,
  isPreviewImg,
  handleSaveImgs,
  handleChangeMultiFormData,
  getFieldDecorator,
  getFieldValue,
  handleRuntimeParams,
  handleInputChange,
  handleDisabledDate,
  customRequest,
  handleChangeAttributeActive,
  isKeyDisabled,
  accept = '',
  beforeUpload,
  dataType,
  notMaxError,
  fileData,
  defaultRadioValue,
  onlyRadio,
  onRemoveImg = () => {},
  className,
  nolabel,
  numberFormatter,
  disabledDate,
  extra = '',
  hidden = false
}) => {
  let fieldElement = ''
  switch (type) {
    case 'text':
    case 'email': {
      const params = {
        type: type,
        placeholder: placeholder,
        disabled: disabled,
        className: className,
        onChange: runtimeRequestParams
          ? (e) =>
              handleRuntimeParams({
                name,
                value: e.target.value,
                runtimeRequestParams
              })
          : handleChangeMultiFormData
            ? (e) => handleChangeMultiFormData(e.target.value, name)
            : false
      }

      if (max) {
        params.maxLength = max
      }
      fieldElement = <Input {...params} />
      break
    }
    case 'hybrid_radio':
      fieldElement = (
        <Input
          type={type}
          placeholder={placeholder}
          disabled={disabled}
          onChange={
            runtimeRequestParams
              ? (e) =>
                  handleRuntimeParams({
                    name,
                    value: e.target.value,
                    runtimeRequestParams
                  })
              : false
          }
        />
      )
      break
    case 'number':
      fieldElement = (
        <InputNumber
          type='number'
          className={`number-format ${className}`}
          decimalSeparator='.'
          formatter={
            numberFormatter
              ? (value) => numberFormatter(value, name)
              : undefined
          }
          parser={
            handleInputChange
              ? (value) => handleInputChange(value, name)
              : undefined
          }
          placeholder={placeholder}
          min={min}
          max={max}
          disabled={disabled}
        />
      )
      break
    case 'date':
    case 'datepicker': {
      const params = {
        disabled: disabled,
        defaultValue: defaultValue,
        placeholder: placeholder || 'DD-MM-YYYY',
        format: 'DD-MM-YYYY'
      }
      if (handleDisabledDate) {
        params.disabledDate = (current) =>
          handleDisabledDate(current, disabledDate)
      }
      fieldElement = (
        <DatePicker
          {...params}
          onChange={(_, dateString) =>
            handleChangeMultiFormData &&
            handleChangeMultiFormData(dateString, name)}
        />
      )
      break
    }
    case 'upload':
      fieldElement = (
        <Upload
          name='upload'
          showUploadList={false}
          customRequest={(data) => customRequest(data, name)}
          listType='picture'
          accept={accept}
          beforeUpload={(file) => {
            return beforeUpload(file, name)
          }}
        >
          <Button>
            <Icon type='upload' /> Click to upload
          </Button>
        </Upload>
      )
      break
    case 'file':
      return (
        <Form.Item label={title} required={required}>
          <UploadImgPreviewContainer
            name={name}
            fileType={accept}
            img={defaultValue}
            isNew={!defaultValue}
            subTitle={subTitle}
            isPreviewImg={isPreviewImg}
            disabled={disabled}
            onSave={(file) => handleSaveImgs(file, name)}
            onRemove={onRemoveImg}
          />
        </Form.Item>
      )
    case 'textarea': {
      const params = {
        placeholder: placeholder || ''
      }

      if (max) {
        params.maxLength = max
      }
      fieldElement = <Input.TextArea disabled={disabled} {...params} />
      break
    }
    case 'search':
      fieldElement = (
        <Select
          placeholder={placeholder}
          disabled={disabled}
          onChange={
            runtimeRequestParams
              ? (e) =>
                  handleRuntimeParams({ name, value: e, runtimeRequestParams })
              : false
          }
        >
          {data.map((value) => (
            <Select.Option
              id={`${name}_${value.code}`}
              value={value.code}
              key={value.code}
            >
              {value.name}
            </Select.Option>
          ))}
        </Select>
      )
      break
    case 'multiple_hybrid_files':
      return (
        <div>
          <label>{title}</label>
          <MultipleHybridFiles
            name={name}
            data={data}
            defaultValue={defaultValue}
            dataType={dataType}
            customRequest={customRequest}
            getFieldDecorator={getFieldDecorator}
            beforeUpload={beforeUpload}
            disabled={disabled}
            handleChangeMultiFormData={handleChangeMultiFormData}
          />
        </div>
      )
    case 'multiple_files_with_radio':
      return (
        <Form.Item label={title} required={required}>
          <MultiFileWithRadio
            name={name}
            radioData={data}
            subTitle={subTitle}
            fileData={fileData}
            fileType={accept}
            disabled={disabled}
            defaultValue={defaultValue}
            defaultRadioValue={defaultRadioValue}
            onChange={handleChangeMultiFormData}
          />
        </Form.Item>
      )
    case 'multiple_files':
      return (
        <Form.Item label={title} required={required}>
          <MultiUploadImgView
            name={name}
            fileType={accept}
            subTitle={subTitle}
            fileData={fileData}
            disabled={disabled}
            defaultValue={defaultValue}
            onChange={handleChangeMultiFormData}
          />
        </Form.Item>
      )
    default:
      break
  }

  if (isEnableType) {
    return (
      <Row type='flex' align='middle' justify='start'>
        {!onlyRadio && (
          <Col span={2}>
            <Form.Item>
              <Checkbox
                onChange={(e) =>
                  handleChangeAttributeActive(e, name, radioDataKey)}
              />
            </Form.Item>
          </Col>
        )}
        <Col span={20}>
          {type === 'hybrid_radio' && (
            <Form.Item label={title}>
              {getFieldDecorator(radioDataKey, {
                initialValue:
                  defaultValue !== undefined
                    ? defaultValue
                    : `${get(data, '[0].value', '')}`,
                rules: [{ required: !isKeyDisabled(name) }]
              })(
                <Radio.Group
                  disabled={disabled}
                  onChange={
                    runtimeRequestParams
                      ? (e) =>
                          handleRuntimeParams({
                            name: radioDataKey,
                            value: e.target.value,
                            runtimeRequestParams,
                            handler: name
                          })
                      : false
                  }
                >
                  {data.map((rd, i) => (
                    <Radio
                      key={`radio_${i}`}
                      value={rd.value}
                      disabled={rd.disabled || false}
                    >
                      {' '}
                      {rd.title}{' '}
                    </Radio>
                  ))}
                </Radio.Group>
              )}
            </Form.Item>
          )}
          {!onlyRadio && (
            <Form.Item
              label={type === 'hybrid_radio' ? '' : title}
              extra={<span id={`subtitle_${name}`}>{subTitle}</span>}
            >
              {getFieldDecorator(name, {
                initialValue:
                  type === 'date' && defaultValue
                    ? moment(defaultValue, 'DD-MM-YYYY')
                    : defaultValue,
                rules: [{ required: !isKeyDisabled(name) }]
              })(fieldElement)}
            </Form.Item>
          )}
        </Col>
      </Row>
    )
  } else {
    const rules = [
      {
        required,
        message: `Please ${type === 'upload' ? 'Upload' : 'Enter'} ${title}!`
      }
    ]
    if (min && type === 'text') {
      rules.push({
        min: min,
        message: `Minimum ${min} characters.`
      })
    }

    if (max && type === 'number' && !notMaxError) {
      rules.push({
        pattern: new RegExp(`^[0-9]{0,${max}}$`),
        message: `Maximum ${max} characters.`
      })
    }
    return hidden
      ? (
        <div />
        )
      : (
        <Form.Item
          label={!nolabel && title}
          extra={`${
          type === 'upload'
            ? 'Max 1 file (image/pdf) with file size 10 MB'
            : extra
        }`}
        >
          {getFieldDecorator(name, {
            initialValue: getInitialValue(type, defaultValue),
            rules
          })(fieldElement)}
        </Form.Item>
        )
  }
}

export default renderFormItems
