import { getHeaderUploadFile } from '../../../../../../helpers/utility'
import { uploadPolicyFileApi } from '../../../config/urls'

export const UPLOAD_ACTION = {
  UPLOAD_POLICY_FILE_REQUEST: 'UPLOAD_POLICY_FILE_REQUEST',
  UPLOAD_POLICY_FILE: 'UPLOAD_POLICY_FILE'
}

export const uploadPolicyFile = (payload) => ({
  type: UPLOAD_ACTION.UPLOAD_POLICY_FILE_REQUEST,
  payload: {
    ...payload,
    headers: getHeaderUploadFile(),
    url: uploadPolicyFileApi,
    method: 'POST'
  }
})
