import { Upload, Icon } from 'antd'
import { UploadImgPreviewStyle } from './index.style'
import { useCallback, useEffect, useState } from 'react'
import { useGetFileUploadUrl } from '../state/hooks/useUploadImgPreviewState'
import getUrlExtension from '../../../../../../helpers/getExtensionUrl'
import CircularLoader from '../../../../../../components/CircularLoader'
import { showNotification } from '../../../../../../components/ShowNotification'

function UploadImgPreview ({
  img, name, isNew, onSave, onRemove, fileType = '.png,.jpg,.jpeg',
  disabled = false, subTitle, isPreviewImg
}) {
  const [editImg, setEditImg] = useState(img)
  const [isShowPreview, setIsShowPreview] = useState(!!isNew)

  useEffect(() => {
    if (!editImg && img) {
      setEditImg(img)
    }
  }, [editImg, img])

  const getUploadImgPreviewPath = useCallback((fileUrl, data) => {
    setEditImg(fileUrl)
    onSave(fileUrl, data.type)
    if (isPreviewImg) {
      setIsShowPreview(false)
    }
  }, [onSave, isPreviewImg])

  const { customRequest, UPLOAD_POLICY_FILE_LOADER } = useGetFileUploadUrl(getUploadImgPreviewPath)

  const handleFileUpload = useCallback((file, name) => {
    const fileArr = file?.file?.name.split('.')
    const ext = fileArr[fileArr.length - 1]
    if (!(fileType.includes(ext))) {
      showNotification('error', `Support file extensions are ${fileType}`)
      return
    }
    customRequest(file, name)
  }, [customRequest, fileType])

  const handleRemoveImg = useCallback((e) => {
    e.stopPropagation()
    setIsShowPreview(true)
    setEditImg('')
    onRemove()
  }, [onRemove])

  return (
    <Upload
      name={name || 'file'}
      multiple={false}
      showUploadList={false}
      accept={fileType}
      customRequest={(file) => handleFileUpload(file, name)}
      disabled={disabled}
    >
      <CircularLoader isSpining={UPLOAD_POLICY_FILE_LOADER}>
        <UploadImgPreviewStyle>
          {
            !isNew && onRemove && !disabled && (
              <div className='remove-img' onClick={handleRemoveImg}>
                <Icon type='close-circle' className='close-circle-icon' />
              </div>
            )
          }
          {
            isShowPreview
              ? (
                <div className='text-center'>
                  <Icon type='upload' />
                  <div>Click to upload</div>
                </div>
                )
              : (getUrlExtension(editImg) === 'pdf')
                  ? (
                    <>
                      <div className='offline-pdf-upload-wrapper' />
                      <object
                        type='application/pdf'
                        data={editImg}
                        width='100%'
                        height='100%'
                        aria-label={name}
                      />
                    </>
                    )
                  : (
                    <img src={editImg} alt='' />
                    )
          }
          {!isNew && <span className='img-name'>{name}</span>}
          {subTitle && <span className='img-name'>{subTitle}</span>}
        </UploadImgPreviewStyle>
      </CircularLoader>
    </Upload>
  )
}

export default UploadImgPreview
