import { Col, Row } from 'antd'
import { useCallback, useState } from 'react'
import { MultiUploadImgViewStyle } from './index.style'
import { getFileNameFromUrl } from '../../../../../helpers/utility'
import UploadImgPreviewContainer from '../UploadImgPreview'

function MultiUploadImgView ({
  name, subTitle, disabled, defaultValue,
  fileData = {}, onChange = () => {}
}) {
  const [imgs, setImgs] = useState((() => {
    return (defaultValue && defaultValue.map(item => item.url)) || []
  })())

  const handleMultipleImg = useCallback((file, name, index) => {
    setImgs(imgs => {
      imgs[index] = file
      onChange(imgs, name)
      return [
        ...imgs
      ]
    })
  }, [onChange])

  const handleRemoveImg = useCallback((index) => {
    setImgs((imgs) => {
      imgs.splice(index, 1)
      onChange(imgs, name)
      return [...imgs]
    }, [])
  }, [onChange, name])

  const handleSaveNewUploadImg = useCallback((file) => {
    setImgs((imgs) => {
      imgs.push(file)
      onChange(imgs, name)
      return [...imgs]
    })
  }, [onChange, name])

  return (
    <MultiUploadImgViewStyle>
      <Row gutter={[16, 16]}>
        {
          imgs.map((img, index) => (
            <Col md={3} xl={3} key={`edit-img-${getFileNameFromUrl(img)}`}>
              <UploadImgPreviewContainer
                onSave={(file) => handleMultipleImg(file, name, index)}
                name={`${name}-${index + 1}`}
                img={img}
                disabled={disabled}
                fileType={`.${fileData.allowed_extensions.join(',.')}`}
                onRemove={() => handleRemoveImg(index)}
              />
            </Col>
          ))
        }
        {
          (imgs.length !== fileData?.max_files) && (
            <Col md={3} xl={3} key='edit-img-upload'>
              <UploadImgPreviewContainer
                onSave={(file) => handleSaveNewUploadImg(file, name)}
                name='new'
                isNew
                fileType={`.${fileData.allowed_extensions.join(',.')}`}
                subTitle={subTitle}
                disabled={disabled}
                onRemove={() => handleRemoveImg()}
              />
            </Col>
          )
        }
      </Row>
    </MultiUploadImgViewStyle>
  )
}

export default MultiUploadImgView
