export const getAddressString = (addressData = {}) => {
  const address = [addressData.address] // this string always present
  if (addressData.city_name && addressData.postal_code) {
    address.push(`${addressData.city_name} ${addressData.postal_code}`)
  }
  if (addressData.province_name) {
    address.push(addressData.province_name)
  }
  return address.join(', ')
}

// get payment status
export function getPaymentStatus (status) {
  if (!status || (status === 'NOT_REQUIRED')) return { text: '-' }
  switch (status) {
    case 'PAID':
      return { text: 'Payment Success', color: COLORS.blue }
    case 'POLICY_CREATED':
    case 'COMPLETED':
    case 'ADDITIONAL_BILL_PAID':
      return { text: 'Paid', color: COLORS.green }
    case 'PAYMENT_FAILED':
    case 'EXPIRED':
    case 'FAILED':
      return { text: 'Payment Failed', color: COLORS.errorDark }
    case 'PROOF_APPROVED':
    case 'VERIFICATION_IN_PROGRESS':
      return { text: 'In Verification Process', color: COLORS.orange }
    case 'PROOF_SUBMITTED':
    case 'PROOF_UNDERPAYMENT':
      return { text: 'Payment Proof Uploaded', color: COLORS.orange }
    case 'PROOF_VERIFICATION_FAILED':
      return { text: 'Payment Verification Failed', color: COLORS.orange }
    case 'MITRA_CONFIRMATION_PENDING':
      return { text: 'Waiting Mitra confirmation', color: COLORS.orange }
    case 'CANCELLED':
      return { text: 'Cancelled', color: COLORS.orange }
    default:
      return { text: 'Waiting for payment', color: COLORS.orange }
  }
}

