import { Col, Row } from 'antd'
import { useCallback, useState } from 'react'
import renderFormItems from '../../../../../helpers/renderFormItems'
import { capitalizeFirstLetter } from '../../../../../helpers/utility'
import { MultipleHybridStyle } from './index.style'

function MultipleHybridFiles ({
  name, dataType = {}, data, defaultValue = [],
  getFieldDecorator, beforeUpload, customRequest,
  handleChangeMultiFormData, disabled
}) {
  const [inputData, setInputData] = useState(defaultValue)

  const handleInputChange = useCallback((val, index, key) => {
    setInputData(oldData => {
      oldData[index][key] = val
      handleChangeMultiFormData && handleChangeMultiFormData(oldData, name)
      return [
        ...oldData
      ]
    })
  }, [handleChangeMultiFormData, name])

  const handleRemoveImg = useCallback((index, key) => {
    // handle delete imgs
    setInputData(oldData => {
      oldData[index][key] = ''
      handleChangeMultiFormData && handleChangeMultiFormData(oldData, name)
      return [
        ...oldData
      ]
    })
  }, [handleChangeMultiFormData, name])

  const renderMultipleElement = useCallback(() => {
    // render multiple files
    return (
      inputData.map((item, index) => {
        const elementArr = []
        for (const key in item) {
          if (['id', 'credit_note'].some(i => i === key)) continue
          elementArr.push(
            <Col key={`${key}_${index}`} span={4} className='box-margin-left'>
              {
                renderFormItems({
                  name: `${key}_${item.id}`,
                  type: dataType[key]?.type,
                  subTitle: dataType[key]?.sub_title,
                  accept: `.${dataType[key]?.allowed_extensions?.join(',.')}`,
                  title: capitalizeFirstLetter(key),
                  defaultValue: item[key],
                  onRemoveImg: () => handleRemoveImg(index, key),
                  handleSaveImgs: (file, name) => handleInputChange(file, index, key),
                  handleInputChange: (value, name) => handleInputChange(value, index, key),
                  handleChangeMultiFormData: (value, name) => handleInputChange(value, index, key),
                  isPreviewImg: true,
                  beforeUpload,
                  disabled,
                  getFieldDecorator,
                  customRequest
                })
              }
            </Col>
          )
        }
        return (
          <Row gutter={[8, 8]} key={`${name}_${index}`}>
            {elementArr}
          </Row>
        )
      })
    )
  }, [
    dataType, inputData, name, disabled,
    getFieldDecorator, beforeUpload,
    customRequest, handleInputChange,
    handleRemoveImg
  ])

  return (
    <MultipleHybridStyle>
      {renderMultipleElement()}
    </MultipleHybridStyle>
  )
}

export default MultipleHybridFiles
