import { resetError, useErrorContextValue, useLoaderContextValue, useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useRef } from 'react'
import { showNotification } from '../../../../../../../components/ShowNotification'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../../../constants'
import { useUploadImgPreviewContextValue } from '../../context'
import { uploadPolicyFile } from '../actions'

export const useUploadImgPreviewServiceCall = (actionsCall = () => {}) => {
  const [uploadState, dispatch] = useUploadImgPreviewContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [uploadState, request]
}

export const useUploadPolicyFile = () => useUploadImgPreviewServiceCall(uploadPolicyFile)

// this function use to upload the file and also use to get the data
export const useGetFileUploadUrl = (getFileData, fileUploadPath = PATH_FOR_AGENT_FILE_UPLOAD) => {
  const [{ uploadPolicyFileData }, uploadPolicyFileReq] = useUploadPolicyFile()
  const [{ UPLOAD_POLICY_FILE_LOADER }] = useLoaderContextValue()
  const [{ uploadPolicyFileStatus }, dispatchError] = useErrorContextValue()
  const that = useRef({
    type: '',
    id: ''
  })

  const customRequest = useCallback(({ file }, type, id) => {
    const formData = new FormData()
    const extFileName = file.name.split('.')[0].trim()
    const fileName = `${extFileName}-${Date.parse(new Date())}`
    formData.append('file', file)
    formData.append('path', `${fileUploadPath}/${fileName}`)
    formData.append('identifier', 'agent')
    that.current.type = type
    that.current.id = id
    uploadPolicyFileReq({ body: formData })
  }, [uploadPolicyFileReq])

  useEffect(() => {
    function resetErrorState (key) {
      dispatchError(resetError({
        [key]: undefined
      }))
    }
    if (uploadPolicyFileStatus === 'success' && that.current.type) {
      getFileData(uploadPolicyFileData.url, { ...that.current })
      resetErrorState('uploadPolicyFileStatus')
      that.current.type = ''
    } else if (uploadPolicyFileStatus && that.current.type) {
      showNotification('error', uploadPolicyFileStatus)
      resetErrorState('uploadPolicyFileStatus')
    }
  }, [getFileData, uploadPolicyFileData, uploadPolicyFileStatus])

  return {
    customRequest,
    UPLOAD_POLICY_FILE_LOADER
  }
}
