import { Button, Col, Divider, Icon, Input, Modal, Row, Select } from 'antd'
import { useCallback, useState } from 'react'
import UploadImgPreviewContainer from '../UploadImgPreview'
import { MultiFileWithRadioStyle } from './index.style'

const FILE_TYPES = ['Premium Note', 'Credit Note', 'Printable SCP']

function MultiFileWithRadio ({
  name, radioData = {}, defaultValue, subTitle,
  fileData, disabled, defaultRadioValue, onChange = () => {}
}) {
  const [selected, setSelected] = useState(defaultValue || [])
  const [fileTypes, setFileTypes] = useState(FILE_TYPES.map(i => ({ value: i, title: i })))
  const [newItem, setNewItem] = useState('')
  const [modalVisible, setModalVisible] = useState(false)
  const [currentIndex, setCurrentIndex] = useState(null)

  const handleFileTypeChange = useCallback((value, index) => {
    setSelected(oldValue => {
      oldValue[index] = {
        ...oldValue[index],
        file_type: value
      }
      onChange(oldValue, name)
      return [
        ...oldValue
      ]
    })
  }, [onChange, name])

  const handleSaveImg = useCallback((imgData, index) => {
    setSelected(oldValue => {
      oldValue[index] = {
        ...oldValue[index],
        url: imgData
      }
      onChange(oldValue, name)
      return [
        ...oldValue
      ]
    })
  }, [onChange, name])

  const handleAddMore = useCallback(() => {
    setSelected(oldData => {
      return [
        ...oldData,
        {
          url: '',
          doc_type: radioData[0]?.value || defaultRadioValue || '',
          file_type: fileTypes[0]?.value || ''
        }
      ]
    })
  }, [radioData, defaultRadioValue, fileTypes])

  const handleRemoveImg = useCallback((index) => {
    setSelected(oldValue => {
      oldValue[index] = {
        ...oldValue[index],
        url: ''
      }
      onChange(oldValue, name)
      return [
        ...oldValue
      ]
    })
  }, [onChange, name])

  const renderFileWithRadio = useCallback((item, index) => {
    // render the multiple files
    return (
      <Col span={4} key={index}>
        <UploadImgPreviewContainer
          name={`${name}_${index}`}
          img={item.url}
          isNew={!item.url}
          disabled={disabled}
          fileType={`.${fileData.allowed_extensions.join(',.')}`}
          onSave={(imgData) => handleSaveImg(imgData, index)}
          onRemove={() => handleRemoveImg(index)}
          isPreviewImg
        />
        <Select
          style={{ width: 150 }}
          placeholder='Select file type'
          value={item?.file_type}
          onChange={(value) => handleFileTypeChange(value, index)}
          disabled={disabled}
          dropdownRender={menu => (
            <div>
              {menu}
              <Divider style={{ margin: '4px 0' }} />
              <div
                onMouseDown={e => e.preventDefault()}
                style={{ padding: '4px 8px', cursor: 'pointer' }}
                onClick={() => { setCurrentIndex(index); setModalVisible(true) }}
              >
                <Icon type='plus' /> Add item
              </div>
            </div>
          )}
        >
          {fileTypes.map(fileType => (
            <Select.Option key={fileType.value} value={fileType.value}>
              {fileType.title}
            </Select.Option>
          ))}
        </Select>
      </Col>

    )
  }, [name, disabled, fileData.allowed_extensions, fileTypes, handleSaveImg, handleRemoveImg, handleFileTypeChange])

  return (
    <MultiFileWithRadioStyle>
      <Row gutter={[16, 16]}>
        {
         selected.map((item, index) => renderFileWithRadio(item, index))
       }
      </Row>

      {subTitle && <Row>{subTitle}</Row>}
      {
         (selected.length < fileData.max_files) && (
           <Button
             type='primary'
             icon='plus'
             onClick={handleAddMore}
             disabled={disabled}
           >
             Add
           </Button>
         )
       }
      <Modal
        title='Add new file type'
        visible={modalVisible}
        onOk={() => {
          if (newItem.trim()) {
            setFileTypes(prev => [...prev, { title: newItem, value: newItem }])
            if (currentIndex !== null) {
              handleFileTypeChange(newItem, currentIndex)
            }
            setNewItem('')
            setCurrentIndex(null)
          }
          setModalVisible(false)
        }}
        onCancel={() => { setModalVisible(false); setCurrentIndex(null) }}
      >
        <Input
          value={newItem}
          onChange={e => setNewItem(e.target.value)}
          placeholder='Enter new type'
        />
      </Modal>
    </MultiFileWithRadioStyle>
  )
}

export default MultiFileWithRadio
